Current best committed score: 6.8094 (v0006)

## Diff of the last committed version
FA2-style deferred-rescaling online softmax: keep acc/sum in the domain of the running max; on a new row max rescale history once (rare for random scores), steady state = 1 __expf + 1 add + 4 FFMA per (row,col) instead of 2 expf + corr rescale FMAs. 6.78 quick TFLOPS (was 6.62).

diff --git a/attention.cu b/attention.cu
index dfeb953..c079177 100644
--- a/attention.cu
+++ b/attention.cu
@@ -142,19 +142,32 @@ __global__ void attention_fwd_kernel(
                 s[r] = warp_sum(partial) * scale;
             }

-            // Fused online softmax + output accumulation (tile size 1).
+            // Fused online softmax + output accumulation (tile size 1),
+            // with FA2-style deferred rescaling: acc/sum are kept in the
+            // domain of the current running max m; only when a new row max
+            // arrives do we rescale history (rare for random scores, ~log S
+            // times per row). Steady state costs 1 expf + 1 FADD + 4 FFMA
+            // per (row, column) instead of 2 expf + corr rescale FMAs.
             // Causal: row grow may only attend columns gcol <= grow.
 #pragma unroll
             for (int r = 0; r < ROWS_PER_WARP; ++r) {
                 if (causal && (grow_first + r) < gcol) continue;  // row can't attend
-                const float m_new = fmaxf(row_max[r], s[r]);
-                const float corr = expf(row_max[r] - m_new);
-                const float p = expf(s[r] - m_new);
-                row_sum[r] = row_sum[r] * corr + p;
+                float p;
+                if (s[r] > row_max[r]) {
+                    // New running max: rescale history, p = exp(0) = 1.
+                    const float rescale = __expf(row_max[r] - s[r]);
+                    row_max[r] = s[r];
+                    row_sum[r] *= rescale;
+#pragma unroll
+                    for (int j = 0; j < D_PER_LANE; ++j) acc[r][j] *= rescale;
+                    p = 1.f;
+                } else {
+                    p = __expf(s[r] - row_max[r]);
+                }
+                row_sum[r] += p;
 #pragma unroll
                 for (int j = 0; j < D_PER_LANE; ++j)
-                    acc[r][j] = acc[r][j] * corr + p * v_f[j];
-                row_max[r] = m_new;
+                    acc[r][j] = fmaf(p, v_f[j], acc[r][j]);
             }
         }
         __syncthreads();


